import{describe,it,expect,beforeAll}from"vitest";import{readFileSync}from"node:fs";import{resolve,dirname}from"node:path";import{fileURLToPath}from"node:url";const __dirname=dirname(fileURLToPath(import.meta.url));function loadDokraData(){const e=readFileSync(resolve(__dirname,"../../dokra-art-explorer/dokra-data.js"),"utf-8");return new Function(e+"\nreturn { DOKRA_INFO, HISTORY_CHAPTERS, LOST_WAX_PROCESS, ARTISAN_COMMUNITIES, GALLERY_IMAGES, REFERENCES };")()}describe("Dokra Art Explorer — Data Tests",()=>{let e;beforeAll(()=>{e=loadDokraData()}),describe("DOKRA_INFO metadata",()=>{it("contains correct Dokra metadata",()=>{expect(e.DOKRA_INFO.id).toBe("dokra-art"),expect(e.DOKRA_INFO.title).toContain("Dokra"),expect(e.DOKRA_INFO.technique).toContain("Lost-Wax"),expect(e.DOKRA_INFO.eraOrigin).toContain("Indus Valley")}),it("has quickStats array with 6 items",()=>{expect(Array.isArray(e.DOKRA_INFO.quickStats)).toBe(!0),expect(e.DOKRA_INFO.quickStats.length).toBe(6)})}),describe("HISTORY_CHAPTERS & LOST_WAX_PROCESS",()=>{it("contains history chapters and lost-wax process steps",()=>{expect(Array.isArray(e.HISTORY_CHAPTERS)).toBe(!0),expect(e.HISTORY_CHAPTERS.length).toBeGreaterThanOrEqual(4),expect(Array.isArray(e.LOST_WAX_PROCESS)).toBe(!0),expect(e.LOST_WAX_PROCESS.length).toBeGreaterThanOrEqual(5)})}),describe("ARTISAN_COMMUNITIES",()=>{it("contains multiple artisan communities",()=>{expect(Array.isArray(e.ARTISAN_COMMUNITIES)).toBe(!0),expect(e.ARTISAN_COMMUNITIES.length).toBeGreaterThanOrEqual(3),expect(e.ARTISAN_COMMUNITIES.some(e=>e.name.includes("Dokra Damar"))).toBe(!0)})}),describe("GALLERY_IMAGES & REFERENCES",()=>{it("has non-empty gallery and references",()=>{expect(Array.isArray(e.GALLERY_IMAGES)).toBe(!0),expect(e.GALLERY_IMAGES.length).toBeGreaterThanOrEqual(2),expect(Array.isArray(e.REFERENCES)).toBe(!0),expect(e.REFERENCES.length).toBeGreaterThanOrEqual(2)})})});